-- Populate memberships table for existing users based on their profile roles INSERT INTO public.memberships (user_id, role, gateway, created_at, updated_at) SELECT id, CASE WHEN role = 'trusted_partner' THEN 'trusted_partner' WHEN role = 'user' THEN 'member' WHEN role = 'admin' THEN 'admin' ELSE 'member' END as role, 'migration' as gateway, created_at, updated_at FROM public.profiles WHERE id NOT IN (SELECT user_id FROM public.memberships) ON CONFLICT (user_id) DO NOTHING;
